using UnityEngine;
using System.Collections;

// 경비 슬라임 (C#) — 비주얼 스크립트 「C# 메서드 부르기」 노드가 이름으로 불러요
//   순찰 상태 진입 → Calm()   · 추격 상태 진입 → Angry()
//   추격 상태 업데이트 → Chase() · 잡음 상태 진입 → Caught()
public class GuardMove : MonoBehaviour
{
    public float chaseSpeed = 3.3f;   // 주인공(1초에 4칸)보다 조금 느리게 — 열심히 뛰면 따돌릴 수 있어요
    public float minX = 1.2f;         // 창고 안쪽 범위 (벽 바깥으로 나가지 않게)
    public float maxX = 15.8f;
    public float minY = 1.2f;
    public float maxY = 9.8f;

    SpriteRenderer sr;
    bool angry = false;
    float animT = 0f;

    void Start()
    {
        sr = GetComponent<SpriteRenderer>();
    }

    // 순찰로 돌아오면 원래 모습
    public void Calm()
    {
        angry = false;
        sr.sprite = "ex_guard";
        transform.localScale = new Vector3(1, 1, 1);
    }

    // 들켰다! 빨개지고 통통 튀며 쫓아와요
    public void Angry()
    {
        angry = true;
        animT = 0f;
        Sfx("들켰다");
    }

    // 주인공 쪽으로 한 프레임만큼 다가가요 (추격 상태의 업데이트에서 매 프레임 불림)
    public void Chase()
    {
        Vector2 target = Hero.main.position;
        transform.position = Vector2.MoveTowards(transform.position, target, chaseSpeed * Time.deltaTime);
        sr.flipX = target.x < transform.position.x;
    }

    // 잡았다! 주인공을 잠깐 멈추고 입구로 돌려보내요
    public void Caught()
    {
        Sfx("잡혔다");
        Hero.main.canMove = false;
        StartCoroutine(SendBack());
    }

    IEnumerator SendBack()
    {
        yield return new WaitForSeconds(1.2f);
        Hero.main.position = new Vector2(2, 6);
        Hero.main.canMove = true;
    }

    void Update()
    {
        if (!angry)
            return;
        // 추격 애니메이션: 화난 그림 두 장을 번갈아 · 위아래로 통통
        animT += Time.deltaTime;
        if (Mathf.FloorToInt(animT * 8f) % 2 == 0)
            sr.sprite = "ex_guard_angry";
        else
            sr.sprite = "ex_guard_angry2";
        float s = 1f + Mathf.Sin(animT * 18f) * 0.08f;
        transform.localScale = new Vector3(2f - s, s, 1);
    }

    // 순찰 · 추격이 어떻게 움직이든 창고 벽 안쪽에만 있게 해요
    void LateUpdate()
    {
        Vector3 p = transform.position;
        transform.position = new Vector3(Mathf.Clamp(p.x, minX, maxX), Mathf.Clamp(p.y, minY, maxY), 0);
    }

    void Sfx(string clip)
    {
        GameObject.Find("효과음").GetComponent<AudioSource>().PlayOneShot(clip);
    }
}

using UnityEngine;

// 효과음 상자 — 비주얼 스크립트가 「C# 메서드 부르기」(대상: 효과음)로 불러요
public class SoundBox : MonoBehaviour
{
    public void Gem()
    {
        GetComponent<AudioSource>().PlayOneShot("보석 반짝");
    }

    public void Door()
    {
        GetComponent<AudioSource>().PlayOneShot("문 열림");
    }
}
